    kani::assert(post::<u8, KeyLess<u8>>(snapshot::<u8, KeyLess<u8>>(&before[begin..begin + tail + 1]), &v[begin..begin + tail + 1]), "S3_INSERT_SORTED_FULL_COUNT");
    for i in 0..34 {
        kani::assert((begin <= i && i <= begin + tail) || v[i] == before[i], "S3_INSERT_OUTSIDE_FRAME");
    }
    kani::cover(tail == 1, "S3_INSERT_LENGTH2");
    kani::cover(tail == 16, "S3_INSERT_LENGTH17");
    kani::cover(begin == 1, "S3_INSERT_BASE_FIRST");
    kani::cover(begin == 16, "S3_INSERT_BASE_LAST");
    kani::cover(before[begin + tail] >= before[begin + tail - 1], "S3_INSERT_EARLY_RETURN");
    kani::cover(before[begin + tail] < before[begin], "S3_INSERT_FULL_SIFT");
    kani::cover(before[begin + tail] == before[begin], "S3_INSERT_DUPLICATE");
    kani::cover(v[begin] < v[begin + tail], "S3_INSERT_NONCONSTANT");
    kani::cover(true, "S3_INSERT_USEFUL_RETURN");
}

#[kani::proof_for_contract(bidirectional_merge)]
#[kani::unwind(12)]
fn s3_merge8_u8_separate() {
    kani::assert(active(), "S3_MERGE8_SEPARATE_ACTIVE");
    let src: [u8; 10] = kani::any();
    kani::assume(ordered(&src[1..5]) && ordered(&src[5..9]));
    let before = src;
    let mut dst = [MaybeUninit::<u8>::uninit(); 10];
    dst[0].write(0xa5); dst[9].write(0x5a);
    unsafe { bidirectional_merge(&src[1..9], dst.as_mut_ptr().add(1).cast(), &mut KeyLess::<u8>::new()) };
    let mut out = [0u8; 8];
    for i in 0..8 { out[i] = unsafe { dst[i + 1].assume_init() }; }
    kani::assert(post::<u8, KeyLess<u8>>(snapshot::<u8, KeyLess<u8>>(&before[1..9]), &out), "S3_MERGE8_SEPARATE_SORTED_FULL_COUNT");
    kani::assert(src == before, "S3_MERGE8_SEPARATE_SOURCE_FRAME");
    kani::assert(unsafe { dst[0].assume_init() == 0xa5 && dst[9].assume_init() == 0x5a }, "S3_MERGE8_SEPARATE_CANARIES");
    kani::cover(src[1] < src[5], "S3_MERGE8_SEPARATE_LEFT_FIRST");
    kani::cover(src[1] > src[5], "S3_MERGE8_SEPARATE_RIGHT_FIRST");
    kani::cover(src[4] == src[5], "S3_MERGE8_SEPARATE_TIE");
    kani::cover(src[4] > src[5], "S3_MERGE8_SEPARATE_UNSORTED");
    kani::cover(out[0] < out[7], "S3_MERGE8_SEPARATE_NONCONSTANT");
    kani::cover(true, "S3_MERGE8_SEPARATE_USEFUL_RETURN");
}

#[kani::proof_for_contract(bidirectional_merge)]
#[kani::unwind(50)]
fn s3_merge8_u8_same_alloc() {
    kani::assert(active(), "S3_MERGE8_SAME_ACTIVE");
    let before: [u8; 48] = kani::any();
    let mut v = [MaybeUninit::<u8>::uninit(); 48];
    let src: usize = kani::any();
    let dst: usize = kani::any();
    kani::assume(src <= 40 && dst <= 40);
    kani::assume(src + 8 <= dst || dst + 8 <= src);
    kani::assume(ordered(&before[src..src + 4]) && ordered(&before[src + 4..src + 8]));
    for i in 0..48 {
        if i < dst || i >= dst + 8 { v[i].write(before[i]); }
    }
    let p = v.as_mut_ptr().cast::<u8>();
    // Only the source range is borrowed. The disjoint destination retains raw provenance.
    unsafe { bidirectional_merge(slice::from_raw_parts(p.add(src), 8), p.add(dst), &mut KeyLess::<u8>::new()) };
    let mut out = [0u8; 8];
    for i in 0..8 { out[i] = unsafe { v[dst+i].assume_init() }; }
    kani::assert(post::<u8, KeyLess<u8>>(snapshot::<u8, KeyLess<u8>>(&before[src..src + 8]), &out), "S3_MERGE8_SAME_SORTED_FULL_COUNT");
    for i in 0..48 {
        kani::assert((dst <= i && i < dst + 8) || unsafe { v[i].assume_init() } == before[i], "S3_MERGE8_SAME_OUTSIDE_FRAME");
    }
    for i in 0..8 {
        kani::assert(unsafe { v[src+i].assume_init() } == before[src+i], "S3_MERGE8_SAME_SOURCE_FRAME");
    }
    let canary: usize = kani::any();
    kani::assume(canary < 48 && (canary < dst || canary >= dst + 8));
    kani::assert(unsafe { v[canary].assume_init() } == before[canary], "S3_MERGE8_SAME_CANARY");
    kani::cover(src + 8 == dst, "S3_MERGE8_SAME_FORWARD_ADJACENT");
    kani::cover(dst + 8 == src, "S3_MERGE8_SAME_REVERSE_ADJACENT");
    kani::cover(src == 40 && dst == 0, "S3_MERGE8_SAME_EXTREME");
    kani::cover(before[src] < before[src + 4], "S3_MERGE8_SAME_LEFT_FIRST");
    kani::cover(before[src] > before[src + 4], "S3_MERGE8_SAME_RIGHT_FIRST");
    kani::cover(before[src + 3] == before[src + 4], "S3_MERGE8_SAME_TIE");
    kani::cover(before[src + 3] > before[src + 4], "S3_MERGE8_SAME_UNSORTED");
    kani::cover(out[0] < out[7], "S3_MERGE8_SAME_NONCONSTANT");
    kani::cover(src == 32 && dst == 0, "S3_MERGE8_SAME_SORT8_FIRST_GEOMETRY");
    kani::cover(src == 40 && dst == 16, "S3_MERGE8_SAME_SORT8_SECOND_GEOMETRY");
    kani::cover(true, "S3_MERGE8_SAME_USEFUL_RETURN");
}

//! Bounded permutation checks with distinct identity tags and arbitrary comparison answers.
//!
//! Each comparison reads both arguments and chooses a fresh bool. No ordering law is assumed.
//! Distinct tags track equal payloads separately, and fresh answers include every answer
//! sequence of a returning comparator. The fixed initial identity order restricts no payload
//! order; see verify.rs for the whole-element transfer assumption and its limits.
//! Tag types match the source types without wrappers; a separate root checks dispatch.
//!
//! Exactly N outputs, range checks, and an all-ones mask imply that each tag occurs once.
//! A u64 mask accommodates 32 tags without a full-width shift. The unwind budget also covers
//! the largest selected route and the tag-check loops.

use super::super::{
    MAX_STACK_ARRAY_SIZE, SMALL_SORT_FALLBACK_THRESHOLD, SMALL_SORT_GENERAL_SCRATCH_LEN,
    SMALL_SORT_GENERAL_THRESHOLD, SMALL_SORT_NETWORK_SCRATCH_LEN, SMALL_SORT_NETWORK_THRESHOLD,
    StableSmallSortTypeImpl, UnstableSmallSortFreezeTypeImpl, UnstableSmallSortTypeImpl,
    has_efficient_in_place_swap,
};
use crate::cell::Cell;
use crate::mem::size_of;
use crate::{kani, ptr};

fn arbitrary_u8_order(a: &u8, b: &u8) -> bool {
    // SAFETY: the real sort must supply initialized, readable comparator arguments.
    unsafe {
        let _ = ptr::read_volatile(a);
        let _ = ptr::read_volatile(b);
    }
    kani::any()
}

#[cfg(kani_smallsort_controls)]
fn abort_on_order_violation() -> ! {
    kani::cover(true, "order violation panic is reachable");
    kani::assume(false);
    unreachable!()
}

// The ordinary networks never reach this panic boundary. Keep the cutoff but omit its cover.
fn abort_without_panic_cover() -> ! {
    kani::assume(false);
    unreachable!()
}

fn check_tags<const N: usize>(tags: &[u64; N]) {
    assert!(N > 0 && N <= 32);
    let mut seen = 0u64;
    for &tag in tags {
        kani::assert(tag < N as u64, "output tag is in range");
        // Keep the shift defined even on a counterexample with an out-of-range tag.
        if tag < N as u64 {
            seen |= 1u64 << tag;
        }
    }
    kani::assert(seen == (1u64 << N) - 1, "every input tag occurs exactly once");
}

fn network_output<const N: usize>() -> [u8; N] {
    let mut v = crate::array::from_fn(|i| i as u8);
    <u8 as UnstableSmallSortTypeImpl>::small_sort(&mut v, &mut arbitrary_u8_order);
    v
}

fn network_body<const N: usize>() {
    let v = network_output::<N>();
    check_tags(&crate::array::from_fn::<_, N, _>(|i| v[i] as u64));
    kani::cover(true, "network returns with every tag");
}

#[kani::proof]
fn tag_types_preserve_source_routes() {
    fn require_freeze_copy<T: crate::slice::sort::shared::FreezeMarker + Copy>() {}
    require_freeze_copy::<u8>();
    require_freeze_copy::<u64>();

    // Unstable u8 takes the Freeze+Copy network specialization and its size branch.
    assert!(size_of::<u8>() == 1);
    assert!(has_efficient_in_place_swap::<u8>());
    assert!(size_of::<u8>() * SMALL_SORT_NETWORK_SCRATCH_LEN <= MAX_STACK_ARRAY_SIZE);
    assert!(<u8 as UnstableSmallSortTypeImpl>::small_sort_threshold() == 32);
    assert!(
        <u8 as UnstableSmallSortFreezeTypeImpl>::small_sort_threshold()
            == SMALL_SORT_NETWORK_THRESHOLD
    );

    // Stable Freeze u64 always selects general, independently of the swap heuristic.
    assert!(size_of::<u64>() == 8);
    assert!(SMALL_SORT_GENERAL_SCRATCH_LEN == 48);
    assert!(
        <u64 as StableSmallSortTypeImpl>::small_sort_threshold() == SMALL_SORT_GENERAL_THRESHOLD
    );
    assert!(SMALL_SORT_GENERAL_THRESHOLD == 32);

    // The Freeze specialization would return 32: 16 identifies the blanket Stable entry.
    assert!(
        <Cell<u8> as StableSmallSortTypeImpl>::small_sort_threshold()
            == SMALL_SORT_FALLBACK_THRESHOLD
    );
    assert!(SMALL_SORT_FALLBACK_THRESHOLD == 16);
    kani::cover(true, "tag and source types select the required routes");
}

#[kani::proof]
#[kani::stub(
    crate::slice::sort::shared::smallsort::panic_on_ord_violation,
    abort_without_panic_cover
)]
#[kani::unwind(34)]
fn network_u8_n9() {
    network_body::<9>();
}

#[kani::proof]
#[kani::stub(
    crate::slice::sort::shared::smallsort::panic_on_ord_violation,
    abort_without_panic_cover
)]
#[kani::unwind(34)]
fn network_u8_n13() {
    network_body::<13>();
}

#[cfg(kani_smallsort_controls)]
#[kani::proof]
#[kani::stub(
    crate::slice::sort::shared::smallsort::panic_on_ord_violation,
    abort_on_order_violation
)]
#[kani::unwind(34)]
fn reject_duplicate_network_u8_n9() {
    let mut v = network_output::<9>();
    kani::cover(true, "duplicate mutant reaches the corruption");
    // SAFETY: both pointers name distinct initialized elements of the same live array.
    // Deliberately lose one identity after the same real sorting call used by the positive root.
    unsafe { ptr::copy(v.as_ptr(), v.as_mut_ptr().add(1), 1) };
    check_tags(&crate::array::from_fn::<_, 9, _>(|i| v[i] as u64));
}

//! Logical-value correctness through real trait entries; no contracts or panic paths are stubbed.

use super::super::{
    SMALL_SORT_GENERAL_SCRATCH_LEN, StableSmallSortTypeImpl, UnstableSmallSortTypeImpl,
};
use crate::cell::Cell;
use crate::kani;
use crate::mem::MaybeUninit;

trait LogicalByte {
    fn new(value: u8) -> Self;
    fn value(&self) -> u8;
}

impl LogicalByte for Cell<u8> {
    fn new(value: u8) -> Self {
        Cell::new(value)
    }

    fn value(&self) -> u8 {
        self.get()
    }
}

#[repr(transparent)]
struct DropKey(u8);

impl crate::ops::Drop for DropKey {
    fn drop(&mut self) {}
}

impl LogicalByte for DropKey {
    fn new(value: u8) -> Self {
        Self(value)
    }

    fn value(&self) -> u8 {
        self.0
    }
}

fn logical_less<T: LogicalByte>(a: &T, b: &T) -> bool {
    a.value() < b.value()
}

fn count(values: &[u8], probe: u8) -> usize {
    let mut count = 0;
    for value in values {
        count += (*value == probe) as usize;
    }
    count
}

fn check_output<const N: usize>(input: &[u8; N], output: &[u8; N], probe: u8) {
    for i in 1..N {
        assert!(output[i - 1] <= output[i]);
    }
    assert!(count(input, probe) == count(output, probe));
    kani::cover(true, "logical sort returns after both assertions");
}

fn cover_nontrivial_input<const N: usize>(input: &[u8; N]) {
    kani::cover(input[0] > input[1], "logical sort returns from an unsorted input");
    kani::cover(input[0] == input[1], "logical sort returns with duplicate keys");
}

// Cell is !Freeze: both trait defaults use insertion or fallback, with threshold 16.
// DropKey is Freeze and non-Copy: stable and unstable dispatch select general, threshold 32.
fn trait_properties<T: LogicalByte, const N: usize>() -> [u8; N] {
    let input: [u8; N] = kani::any();
    let probe: u8 = kani::any();
    let mut values: [T; N] = crate::array::from_fn(|i| T::new(input[i]));
    let stable: bool = kani::any();
    if stable {
        let mut scratch = [const { MaybeUninit::<T>::uninit() }; SMALL_SORT_GENERAL_SCRATCH_LEN];
        <T as StableSmallSortTypeImpl>::small_sort(
            &mut values,
            &mut scratch,
            &mut logical_less::<T>,
        );
    } else {
        <T as UnstableSmallSortTypeImpl>::small_sort(&mut values, &mut logical_less::<T>);
    }
    let output = crate::array::from_fn(|i| values[i].value());
    check_output(&input, &output, probe);
    kani::cover(stable, "logical stable trait entry returns");
    kani::cover(!stable, "logical unstable trait entry returns");
    input
}

fn trivial_trait_properties<T: LogicalByte>() {
    let selector: u8 = kani::any();
    match selector {
        0 => {
            trait_properties::<T, 0>();
        }
        1 => {
            trait_properties::<T, 1>();
        }
        _ => cover_nontrivial_input(&trait_properties::<T, 2>()),
    }
    kani::cover(selector == 0, "logical length zero");
    kani::cover(selector == 1, "logical length one");
    kani::cover(selector == 2, "logical length two");
}

// The unwind budget covers element construction, sorting, and logical-value count loops.
// Solver choice is specific to these logical-value models.
macro_rules! trait_cases {
    ($name:ident, $t:ty, [0, 1, 2]) => {
        #[kani::proof]
        #[kani::solver(cadical)]
        #[kani::unwind(50)]
        fn $name() {
            trivial_trait_properties::<$t>();
        }
    };
}

trait_cases!(sorted_permutation_traits_fallback_cell_u8_n0_to2, Cell<u8>, [0, 1, 2]);
trait_cases!(sorted_permutation_traits_general_drop_u8_n0_to2, DropKey, [0, 1, 2]);

macro_rules! fixed_trait_case {
    ($name:ident, $t:ty, $n:literal) => {
        #[kani::proof]
        #[kani::solver(cadical)]
        #[kani::unwind(50)]
        fn $name() {
            cover_nontrivial_input(&trait_properties::<$t, $n>());
        }
    };
}

// A single length keeps solver time within the ordinary budget.
fixed_trait_case!(sorted_permutation_traits_fallback_cell_u8_n7, Cell<u8>, 7);

fixed_trait_case!(sorted_permutation_traits_general_drop_u8_n8, DropKey, 8);

// Fixed routes check each Cell branch independently.
// The two const values cover both dispatch choices without restricting keys.
fn fixed_route_trait_properties<T: LogicalByte, const N: usize, const STABLE: bool>() {
    let input: [u8; N] = kani::any();
    let probe: u8 = kani::any();
    let mut values: [T; N] = crate::array::from_fn(|i| T::new(input[i]));
    if STABLE {
        let mut scratch = [const { MaybeUninit::<T>::uninit() }; SMALL_SORT_GENERAL_SCRATCH_LEN];
        <T as StableSmallSortTypeImpl>::small_sort(
            &mut values,
            &mut scratch,
            &mut logical_less::<T>,
        );
    } else {
        <T as UnstableSmallSortTypeImpl>::small_sort(&mut values, &mut logical_less::<T>);
    }
    let output = crate::array::from_fn(|i| values[i].value());
    check_output(&input, &output, probe);
    cover_nontrivial_input(&input);
}

macro_rules! fixed_route_trait_case {
    ($name:ident, $t:ty, $n:literal, $stable:literal) => {
        #[kani::proof]
        #[kani::solver(cadical)]
        #[kani::unwind(50)]
        fn $name() {
            fixed_route_trait_properties::<$t, $n, $stable>();
            // Emit only the selected route's cover; the opposite const branch cannot return.
            kani::cover(true, concat!("logical fixed trait entry returns: stable=", $stable));
        }
    };
}

fixed_route_trait_case!(sorted_permutation_traits_stable_fallback_cell_u8_n8, Cell<u8>, 8, true);
fixed_route_trait_case!(sorted_permutation_traits_unstable_fallback_cell_u8_n8, Cell<u8>, 8, false);
